insert into dishes values ('bruschetta-al-pomodoro', 'Bruschetta al pomodoro', 'Pão de fermentação natural tostado na brasa, esfregado com alho, coberto com tomates italianos em cubos, manjericão fresco e azeite extravirgem da Puglia.', 3800, 'entradas', '/images/dishes/bruschetta-al-pomodoro.webp', 'Foto ilustrativa · Unsplash', 10, 2, array['Pão de fermentação natural','Tomate italiano','Alho','Manjericão','Azeite extravirgem','Flor de sal']::text[], array['Glúten']::text[], false, true, null) on conflict (id) do nothing;
